 import React, { useState, useEffect } from 'react'
import { supabase } from '../lib/supabase'
import { useAuth } from '../contexts/AuthContext'
import { footballApi, generateAIPrediction, getTeamEmoji } from '../services/footballApi'

export default function Matches() {
    const { user, profile } = useAuth()
    const [matches, setMatches] = useState([])
    const [loading, setLoading] = useState(true)
    const [filter, setFilter] = useState('all')
    const [showModal, setShowModal] = useState(false)
    const [selectedMatch, setSelectedMatch] = useState(null)
    const [prediction, setPrediction] = useState({
        result: 'Draw',
        yellowCards: 2,
        redCards: 0,
        corners: 5,
        offsides: 1
    })
    const [submitting, setSubmitting] = useState(false)
    const [sharedPredictions, setSharedPredictions] = useState({})

    useEffect(() => {
        loadMatches()
        if (user) {
            loadUserSharedPredictions()
        }
    }, [filter, user])

    const loadMatches = async () => {
        setLoading(true)
        try {
            let events = await footballApi.getTodaysMatches()
            
            // Apply filters
            let filtered = events
            if (filter === 'today') {
                const today = new Date().toISOString().split('T')[0]
                filtered = events.filter(m => m.dateEvent === today)
            } else if (filter === 'upcoming') {
                const now = new Date()
                filtered = events.filter(m => new Date(m.dateEvent) > now)
            } else if (filter === 'live') {
                filtered = events.filter(m => m.strStatus === 'LIVE' || m.strStatus === 'In Progress')
            }
            
            setMatches(filtered)
        } catch (error) {
            console.error('Error loading matches:', error)
        } finally {
            setLoading(false)
        }
    }

    const loadUserSharedPredictions = async () => {
        try {
            const { data, error } = await supabase
                .from('shared_predictions')
                .select('match_id')
                .eq('user_id', user.id)
            
            if (!error && data) {
                const shared = {}
                data.forEach(p => {
                    shared[p.match_id] = true
                })
                setSharedPredictions(shared)
            }
        } catch (error) {
            console.error('Error loading shared predictions:', error)
        }
    }

    const openPredictionModal = (match) => {
        if (!user) {
            alert('Please sign in to make predictions')
            return
        }
        setSelectedMatch(match)
        setPrediction({
            result: 'Draw',
            yellowCards: 2,
            redCards: 0,
            corners: 5,
            offsides: 1
        })
        setShowModal(true)
    }

    const closeModal = () => {
        setShowModal(false)
        setSelectedMatch(null)
    }

    const handleSubmitPrediction = async () => {
        if (!selectedMatch || !user) return
        
        setSubmitting(true)
        try {
            // Save prediction to database
            const { data, error } = await supabase
                .from('shared_predictions')
                .insert({
                    user_id: user.id,
                    match_id: selectedMatch.idEvent,
                    prediction_data: prediction,
                    shared_at: new Date().toISOString()
                })
                .select()
            
            if (error) throw error
            
            // Update user points
            const pointsEarned = 10 + (prediction.yellowCards * 2) + (prediction.corners * 1)
            
            // Update profile points
            const { error: updateError } = await supabase
                .from('profiles')
                .update({ 
                    points: (profile?.points || 0) + pointsEarned,
                    predictions_count: (profile?.predictions_count || 0) + 1
                })
                .eq('id', user.id)
            
            if (updateError) throw updateError
            
            // Mark as shared
            setSharedPredictions(prev => ({
                ...prev,
                [selectedMatch.idEvent]: true
            }))
            
            alert(`✅ Prediction shared! You earned ${pointsEarned} points!`)
            closeModal()
            
            // Refresh data
            await loadUserSharedPredictions()
            window.location.reload()
            
        } catch (error) {
            console.error('Error submitting prediction:', error)
            alert('Failed to submit prediction. Please try again.')
        } finally {
            setSubmitting(false)
        }
    }

    const renderMatchCard = (match) => {
        const homeName = match.strHomeTeam || 'Home'
        const awayName = match.strAwayTeam || 'Away'
        const homeEmoji = getTeamEmoji(homeName)
        const awayEmoji = getTeamEmoji(awayName)
        const ai = generateAIPrediction(match)
        const isShared = sharedPredictions[match.idEvent]
        
        let resultText = 'Draw'
        if (ai.result.home > ai.result.draw && ai.result.home > ai.result.away) resultText = '🏠 Home Win'
        else if (ai.result.away > ai.result.home && ai.result.away > ai.result.draw) resultText = '✈️ Away Win'

        const matchDate = match.dateEvent ? new Date(match.dateEvent) : new Date()
        const dateStr = matchDate.toLocaleDateString('en-US', { 
            weekday: 'short', 
            month: 'short', 
            day: 'numeric' 
        })
        const timeStr = matchDate.toLocaleTimeString('en-US', { 
            hour: '2-digit', 
            minute: '2-digit' 
        })

        const isLive = match.strStatus === 'LIVE' || match.strStatus === 'In Progress'
        const isFinished = match.strStatus === 'FT' || match.strStatus === 'Finished'

        return (
            <div key={match.idEvent} className="bg-white rounded-xl shadow-md overflow-hidden hover:shadow-lg transition">
                <div className="p-4">
                    {/* League & Status */}
                    <div className="flex justify-between items-center mb-3">
                        <span className="text-xs text-gray-500 font-medium">
                            🏆 {match.strLeague || 'Unknown League'}
                        </span>
                        <div className="flex items-center gap-2">
                            {isShared && (
                                <span className="text-xs bg-green-100 text-green-700 px-2 py-0.5 rounded-full">
                                    ✓ Shared
                                </span>
                            )}
                            {isLive && (
                                <span className="text-xs bg-red-500 text-white px-2 py-1 rounded-full animate-pulse">
                                    ● LIVE
                                </span>
                            )}
                            {isFinished && (
                                <span className="text-xs bg-gray-300 text-gray-700 px-2 py-1 rounded-full">
                                    ✅ Finished
                                </span>
                            )}
                        </div>
                    </div>

                    {/* Teams */}
                    <div className="flex items-center justify-between py-3">
                        <div className="flex items-center gap-3">
                            <span className="text-3xl">{homeEmoji}</span>
                            <span className="font-semibold text-gray-800">{homeName}</span>
                        </div>
                        <div className="flex flex-col items-center">
                            <span className="text-sm text-gray-400">vs</span>
                            {isLive || isFinished ? (
                                <span className="font-bold text-lg text-green-600">
                                    {match.intHomeScore || 0} - {match.intAwayScore || 0}
                                </span>
                            ) : null}
                        </div>
                        <div className="flex items-center gap-3">
                            <span className="font-semibold text-gray-800">{awayName}</span>
                            <span className="text-3xl">{awayEmoji}</span>
                        </div>
                    </div>

                    {/* Date & Time */}
                    <div className="text-xs text-gray-500 text-center py-1">
                        📅 {dateStr} at {timeStr}
                    </div>

                    {/* AI Prediction */}
                    <div className="mt-3 bg-gray-50 rounded-lg p-3">
                        <div className="flex items-center justify-between">
                            <span className="text-xs text-gray-500">🤖 AI Prediction</span>
                            <span className="font-semibold text-green-600">{resultText}</span>
                            <span className="text-xs text-gray-400">{ai.confidence}% confidence</span>
                        </div>
                        <div className="flex items-center justify-between text-xs text-gray-400 mt-1">
                            <span>🟨 {ai.yellowCards.home + ai.yellowCards.away} cards</span>
                            <span>🟥 {ai.redCards.home + ai.redCards.away} reds</span>
                            <span>🏁 {ai.corners.home + ai.corners.away} corners</span>
                            <span>🚩 {ai.offsides.home + ai.offsides.away} offsides</span>
                        </div>
                    </div>

                    {/* Predict Button */}
                    {!isFinished && (
                        <button 
                            onClick={() => openPredictionModal(match)}
                            disabled={isShared}
                            className={`w-full mt-3 py-2 rounded-lg font-medium transition ${
                                isShared 
                                    ? 'bg-gray-300 text-gray-500 cursor-not-allowed' 
                                    : 'bg-green-600 text-white hover:bg-green-700'
                            }`}
                        >
                            {isShared ? '✓ Prediction Shared' : '+ Share Your Prediction'}
                        </button>
                    )}
                    {isFinished && (
                        <div className="w-full mt-3 py-2 text-center text-sm text-gray-400 bg-gray-100 rounded-lg">
                            Match finished
                        </div>
                    )}
                </div>
            </div>
        )
    }

    return (
        <div>
            {/* Header */}
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-6 gap-4">
                <div>
                    <h1 className="text-2xl font-bold text-gray-800">📅 Matches</h1>
                    <p className="text-gray-500">View matches and share your predictions</p>
                </div>
                
                {/* Filter Buttons */}
                <div className="flex gap-2 flex-wrap">
                    <button
                        onClick={() => setFilter('all')}
                        className={`px-4 py-2 rounded-lg text-sm font-medium transition ${
                            filter === 'all' 
                                ? 'bg-green-600 text-white' 
                                : 'bg-gray-200 text-gray-700 hover:bg-gray-300'
                        }`}
                    >
                        All
                    </button>
                    <button
                        onClick={() => setFilter('today')}
                        className={`px-4 py-2 rounded-lg text-sm font-medium transition ${
                            filter === 'today' 
                                ? 'bg-green-600 text-white' 
                                : 'bg-gray-200 text-gray-700 hover:bg-gray-300'
                        }`}
                    >
                        Today
                    </button>
                    <button
                        onClick={() => setFilter('upcoming')}
                        className={`px-4 py-2 rounded-lg text-sm font-medium transition ${
                            filter === 'upcoming' 
                                ? 'bg-green-600 text-white' 
                                : 'bg-gray-200 text-gray-700 hover:bg-gray-300'
                        }`}
                    >
                        Upcoming
                    </button>
                    <button
                        onClick={() => setFilter('live')}
                        className={`px-4 py-2 rounded-lg text-sm font-medium transition ${
                            filter === 'live' 
                                ? 'bg-red-600 text-white' 
                                : 'bg-gray-200 text-gray-700 hover:bg-gray-300'
                        }`}
                    >
                        🔴 Live
                    </button>
                </div>
            </div>

            {/* Matches Grid */}
            {loading ? (
                <div className="text-center py-12">
                    <div className="text-gray-500">Loading matches...</div>
                </div>
            ) : matches.length === 0 ? (
                <div className="text-center py-12 bg-white rounded-xl shadow-md">
                    <div className="text-4xl mb-4">⚽</div>
                    <p className="text-gray-500">No matches found</p>
                    <p className="text-sm text-gray-400">Check back later for upcoming games</p>
                </div>
            ) : (
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    {matches.map(renderMatchCard)}
                </div>
            )}

            {/* Match Count */}
            {!loading && matches.length > 0 && (
                <div className="text-center text-sm text-gray-400 mt-6">
                    Showing {matches.length} matches
                </div>
            )}

            {/* ============================================ */}
            {/* PREDICTION MODAL */}
            {/* ============================================ */}
            {showModal && selectedMatch && (
                <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
                    <div className="bg-white rounded-2xl max-w-md w-full max-h-[90vh] overflow-y-auto">
                        <div className="p-6">
                            {/* Modal Header */}
                            <div className="flex justify-between items-center mb-4">
                                <h2 className="text-xl font-bold text-gray-800">📊 Share Prediction</h2>
                                <button 
                                    onClick={closeModal}
                                    className="text-gray-400 hover:text-gray-600 text-2xl"
                                >
                                    ×
                                </button>
                            </div>

                            {/* Match Info */}
                            <div className="bg-gray-50 rounded-lg p-3 mb-4 text-center">
                                <div className="font-semibold">
                                    {selectedMatch.strHomeTeam || 'Home'} vs {selectedMatch.strAwayTeam || 'Away'}
                                </div>
                                <div className="text-sm text-gray-500">
                                    {selectedMatch.strLeague || 'Unknown League'}
                                </div>
                            </div>

                            {/* Prediction Form */}
                            <div className="space-y-4">
                                {/* Result */}
                                <div>
                                    <label className="block text-sm font-medium text-gray-700 mb-2">
                                        🏆 Result
                                    </label>
                                    <div className="grid grid-cols-3 gap-2">
                                        {['Home Win', 'Draw', 'Away Win'].map((result) => (
                                            <button
                                                key={result}
                                                onClick={() => setPrediction({...prediction, result})}
                                                className={`px-3 py-2 rounded-lg text-sm font-medium transition ${
                                                    prediction.result === result
                                                        ? 'bg-green-600 text-white'
                                                        : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
                                                }`}
                                            >
                                                {result === 'Home Win' ? '🏠 Home' : 
                                                 result === 'Away Win' ? '✈️ Away' : '🤝 Draw'}
                                            </button>
                                        ))}
                                    </div>
                                </div>

                                {/* Stats */}
                                <div className="grid grid-cols-2 gap-3">
                                    <div>
                                        <label className="block text-sm font-medium text-gray-700 mb-1">
                                            🟨 Yellow Cards
                                        </label>
                                        <input
                                            type="number"
                                            min="0"
                                            max="10"
                                            value={prediction.yellowCards}
                                            onChange={(e) => setPrediction({...prediction, yellowCards: parseInt(e.target.value) || 0})}
                                            className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-green-500"
                                        />
                                    </div>
                                    <div>
                                        <label className="block text-sm font-medium text-gray-700 mb-1">
                                            🟥 Red Cards
                                        </label>
                                        <input
                                            type="number"
                                            min="0"
                                            max="5"
                                            value={prediction.redCards}
                                            onChange={(e) => setPrediction({...prediction, redCards: parseInt(e.target.value) || 0})}
                                            className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-green-500"
                                        />
                                    </div>
                                    <div>
                                        <label className="block text-sm font-medium text-gray-700 mb-1">
                                            🏁 Corners
                                        </label>
                                        <input
                                            type="number"
                                            min="0"
                                            max="20"
                                            value={prediction.corners}
                                            onChange={(e) => setPrediction({...prediction, corners: parseInt(e.target.value) || 0})}
                                            className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-green-500"
                                        />
                                    </div>
                                    <div>
                                        <label className="block text-sm font-medium text-gray-700 mb-1">
                                            🚩 Offsides
                                        </label>
                                        <input
                                            type="number"
                                            min="0"
                                            max="10"
                                            value={prediction.offsides}
                                            onChange={(e) => setPrediction({...prediction, offsides: parseInt(e.target.value) || 0})}
                                            className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-green-500"
                                        />
                                    </div>
                                </div>

                                {/* Points Preview */}
                                <div className="bg-yellow-50 rounded-lg p-3 text-center">
                                    <p className="text-sm text-gray-600">
                                        Points you could earn: 
                                        <span className="font-bold text-green-600 ml-1">
                                            {10 + (prediction.yellowCards * 2) + (prediction.corners * 1)}
                                        </span>
                                    </p>
                                </div>

                                {/* Submit Button */}
                                <button
                                    onClick={handleSubmitPrediction}
                                    disabled={submitting}
                                    className="w-full bg-green-600 text-white py-3 rounded-lg font-semibold hover:bg-green-700 transition disabled:opacity-50"
                                >
                                    {submitting ? 'Sharing...' : '🚀 Share Prediction'}
                                </button>
                            </div>
                        </div>
                    </div>
                </div>
            )}
        </div>
    )
}
